CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS games (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,description TEXT,image_url VARCHAR(500) NULL,steam_appid INT UNSIGNED NULL,featured TINYINT(1) NOT NULL DEFAULT 0,published TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS updates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,game_id INT UNSIGNED NOT NULL,title VARCHAR(255) NOT NULL,body MEDIUMTEXT,body_format VARCHAR(32) NOT NULL DEFAULT 'text',source_name VARCHAR(120) NOT NULL,source_url VARCHAR(1000),external_id VARCHAR(255) UNIQUE NULL,published_at DATETIME NOT NULL,verified TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(game_id) REFERENCES games(id) ON DELETE CASCADE,INDEX(game_id,published_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sources (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,game_id INT UNSIGNED NULL,name VARCHAR(160) NOT NULL,type VARCHAR(40) NOT NULL DEFAULT 'json',endpoint VARCHAR(1000) NOT NULL,method VARCHAR(10) NOT NULL DEFAULT 'GET',headers TEXT NULL,mapping_json TEXT NULL,enabled TINYINT(1) NOT NULL DEFAULT 1,verified TINYINT(1) NOT NULL DEFAULT 0,interval_minutes INT UNSIGNED NOT NULL DEFAULT 60,last_run_at DATETIME NULL,last_status VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(game_id),FOREIGN KEY(game_id) REFERENCES games(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,action VARCHAR(120) NOT NULL,details TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
